        FastScanner sc = new FastScanner();
        int N = sc.nextInt();
        int K = sc.nextInt();

        if (K == 0) {
            long ans = 0;
            long run = 0;
            for (int i = 0; i < N; i++) {
                int x = sc.nextInt();
                if (x == 0) {
                    run++;
                } else {
                    ans += run * (run + 1) / 2;
                    run = 0;
                }
            }
            ans += run * (run + 1) / 2;
            System.out.println(ans);
            return;
        }

        int mod = K + 1;
        int[] freq = new int[mod];
        int[] queue = new int[N + 1];
        int head = 0, tail = 0;

        queue[tail++] = 0;
        freq[0] = 1;

        int sum = 0;
        long ans = 0;

        for (int i = 0; i < N; i++) {
            int x = sc.nextInt();
            sum += x;

            int lower = sum - K;
            while (head < tail && queue[head] < lower) {
                int p = queue[head++];
                freq[p % mod]--;
            }

            if (sum >= K) {
                int key = sum - K;
                ans += freq[key % mod];
            }

            freq[sum % mod]++;
            queue[tail++] = sum;
        }

        System.out.println(ans);
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

